import {
  ChangeDetectionStrategy, Component, ViewEncapsulation, computed, input, model, output, signal,
} from '@angular/core';
import { HrmAlert, HrmEmpty, HrmProgress, HrmStepper, HrmStepperStep } from 'hrm-ui';

/**
 * @file Form Design System — phần BỔ SUNG cho 2 trait "hàng loạt" của bộ shell trong `_form-ds.ts`:
 *   - `bulk-target`  → áp MỘT thao tác cho NHIỀU đối tượng (điều chỉnh lương hàng loạt, gán ca,
 *                      thêm phụ cấp, chuyển phòng ban, đăng ký đào tạo…)
 *   - `import-map`   → nhập dữ liệu hàng loạt TỪ TỆP (import nhân viên, bảng công, lương, số dư phép)
 *
 * Cùng triết lý với `_form-ds.ts`: form KHÔNG phân loại theo tên nghiệp vụ mà theo **Layout × Trait**.
 * Nghiệp vụ mới = chọn 1 layout + N trait ⇒ thêm cấu hình, KHÔNG thêm component.
 *
 * SỐ CỘT / DẠNG HIỂN THỊ bám **bề rộng container** (CSS Container Queries) — dùng đúng kỹ thuật của
 * `VnrExpenseTable`: bảng cho container rộng, tự đổ về thẻ khi container hẹp (không cuộn ngang).
 * Container `vnrform` do `vnr-form-shell` tạo ra; đặt 2 component này bên trong shell để có hiệu lực.
 *
 * RANH GIỚI KIẾN TRÚC (thực thi bằng THIẾT KẾ, không bằng lời nhắc):
 *   - KHÔNG tự quyết đối tượng nào đủ điều kiện, KHÔNG tự tính before/after.
 *   - KHÔNG tự đọc tệp, KHÔNG tự validate dữ liệu, KHÔNG tự chạy tiến trình nhập.
 *   Mọi con số nghiệp vụ do tầng domain tính sẵn rồi truyền vào; UI chỉ hiển thị và bắn sự kiện.
 *
 * File này là ỨNG VIÊN để chuyển lên `libs/hrm-ui` sau khi nghiệm thu trên template.
 */

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · bulk-target — một thao tác, nhiều đối tượng
// ══════════════════════════════════════════════════════════════════════════════

/** Một đối tượng nhận thao tác hàng loạt (nhân viên / hợp đồng / bản ghi công…). */
export interface VnrBulkTarget {
  readonly id: string;
  readonly name: string;
  /** Dòng phụ: mã NV · phòng ban · vị trí… */
  readonly sub?: string | null;
  /** Do domain service quyết định — UI KHÔNG tự suy luận điều kiện. */
  readonly eligible: boolean;
  /** Lý do không đủ điều kiện, hiển thị bằng CHỮ (không chỉ dựa vào màu). */
  readonly reason?: string | null;
}

/** Một dòng xem trước "trước → sau" — ĐÃ TÍNH sẵn bởi caller. */
export interface VnrBulkPreviewRow {
  readonly id: string;
  readonly label: string;
  readonly before: string;
  readonly after: string;
  /** false = không đổi ⇒ làm mờ để mắt bỏ qua. */
  readonly changed: boolean;
}

/** Kết quả áp dụng — cho phép THÀNH CÔNG MỘT PHẦN (đặc thù thao tác hàng loạt). */
export interface VnrBulkResult {
  readonly ok: number;
  readonly failed: number;
  /** Ghi chú thất bại do domain service sinh, vd "3 nhân viên đang nghỉ thai sản". */
  readonly failedNote?: string | null;
}

/**
 * Bảng chọn đối tượng cho thao tác hàng loạt + xem trước thay đổi + kết quả một phần.
 *
 * RANH GIỚI: component KHÔNG tự chấm "đủ điều kiện" (luật khác nhau theo từng thao tác:
 * điều chỉnh lương xét ngày vào làm, gán ca xét hợp đồng, đăng ký đào tạo xét ngân sách…)
 * và KHÔNG tự tính before/after. Nó chỉ ĐẾM để hiển thị, chọn/bỏ chọn, và bắn sự kiện.
 * ⇒ Dùng lại được cho: điều chỉnh lương · gán ca · thêm phụ cấp · chuyển phòng ban · đăng ký đào tạo.
 */
@Component({
  selector: 'vnr-bulk-target-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmEmpty],
  template: `
    <div class="vnr-bt">
      <!-- Tóm tắt: chỉ ĐẾM thuần tuý trên dữ liệu đã nhận, không suy luận nghiệp vụ -->
      <div class="vnr-bt__sum">
        <span class="c">Đã chọn <b>{{ selectedCount() }}</b> / <b>{{ total() }}</b></span>
        @if (ineligibleCount()) {
          <span class="dot">·</span>
          <span class="ne">{{ ineligibleCount() }} không đủ điều kiện</span>
        }
        <span class="sp"></span>
        @if (eligibleIds().length) {
          <button type="button" class="vnr-bt__b" (click)="toggleAll()">
            {{ allSelected() ? 'Bỏ chọn tất cả' : 'Chọn tất cả đủ điều kiện' }}
          </button>
        }
      </div>

      <div class="vnr-bt__list">
        @for (t of targets(); track t.id) {
          <label class="vnr-bt__it" [class.is-sel]="isSel(t.id)" [class.is-off]="!t.eligible">
            <input type="checkbox" [checked]="isSel(t.id)" [disabled]="!t.eligible" (change)="toggle(t)" />
            <span class="tx">
              <span class="nm">{{ t.name }}</span>
              @if (t.sub) { <span class="sb">{{ t.sub }}</span> }
              <!-- Không đủ điều kiện: nêu LÝ DO bằng chữ, không chỉ làm mờ -->
              @if (!t.eligible) { <span class="rs">{{ t.reason || 'Không đủ điều kiện áp dụng' }}</span> }
            </span>
          </label>
        } @empty {
          <hrm-empty preset="no-data" description="Chưa có đối tượng nào." />
        }
      </div>

      <div class="vnr-bt__ft">
        <button type="button" class="vnr-bt__b" [disabled]="!selectedCount()" (click)="togglePreview()">
          {{ showPreview() ? 'Ẩn xem trước' : 'Xem trước thay đổi' }}
        </button>
        <span class="sp"></span>
        <button type="button" class="vnr-bt__b is-primary" [disabled]="!selectedCount()"
          (click)="apply.emit(selectedIds())">
          {{ applyLabel() }} ({{ selectedCount() }})
        </button>
      </div>

      @if (showPreview()) {
        <div class="vnr-bt__pv">
          <div class="vnr-bt__pvhd">
            <span class="t">Xem trước thay đổi</span>
            <span class="m">{{ changedCount() }}/{{ previewRows().length }} dòng thực sự thay đổi</span>
          </div>

          <table class="vnr-bt__tb">
            <thead><tr><th>Nội dung</th><th>Hiện tại</th><th class="ar"></th><th>Sau khi áp dụng</th></tr></thead>
            <tbody>
              @for (r of previewRows(); track r.id) {
                <tr [class.is-same]="!r.changed">
                  <td class="lb">{{ r.label }}</td>
                  <td class="vl">{{ r.before }}</td>
                  <td class="ar">→</td>
                  <td class="vl new">{{ r.after }}</td>
                </tr>
              } @empty {
                <tr><td class="vnr-bt__empty" [attr.colspan]="4">Chưa có dữ liệu xem trước.</td></tr>
              }
            </tbody>
          </table>

          <!-- Card fallback (container hẹp) — cùng dữ liệu, không cuộn ngang -->
          <div class="vnr-bt__cards">
            @for (r of previewRows(); track r.id) {
              <div class="vnr-bt__card" [class.is-same]="!r.changed">
                <span class="lb">{{ r.label }}</span>
                <span class="pair"><span class="vl">{{ r.before }}</span><span class="ar">→</span><span class="vl new">{{ r.after }}</span></span>
                @if (!r.changed) { <span class="sm">Không đổi</span> }
              </div>
            } @empty {
              <div class="vnr-bt__empty">Chưa có dữ liệu xem trước.</div>
            }
          </div>
        </div>
      }

      @if (result(); as r) {
        <div class="vnr-bt__rs" [attr.data-tone]="r.failed > 0 ? 'partial' : 'ok'">
          <div class="line">
            <span class="k">Thành công</span><b class="v ok">{{ fmt(r.ok) }}</b>
            <span class="dot">·</span>
            <span class="k">Thất bại</span><b class="v fa">{{ fmt(r.failed) }}</b>
          </div>
          @if (r.failedNote) { <div class="nt">{{ r.failedNote }}</div> }
        </div>
      }
    </div>
  `,
  styles: [`
    .vnr-bt { display: flex; flex-direction: column; gap: var(--space-2-5, 10px); }

    .vnr-bt__sum { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2, 8px);
      padding: 8px 12px; border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface-subtle); font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-bt__sum b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .vnr-bt__sum .dot { color: var(--text-soft); }
    .vnr-bt__sum .ne { color: var(--warning-base); font-weight: var(--font-semibold, 600); font-variant-numeric: tabular-nums; }
    .vnr-bt__sum .sp { margin-inline-start: auto; }

    /* Số cột khai trên phần tử CON của container (shell mới mang container-type) */
    .vnr-bt__list { display: grid; grid-template-columns: 1fr; gap: 6px; }
    @container vnrform (min-width: 760px)  { .vnr-bt__list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
    @container vnrform (min-width: 1080px) { .vnr-bt__list { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
    /* Rỗng cấp panel: chiếm trọn bề ngang lưới, không bị bóp vào 1 cột */
    .vnr-bt__list hrm-empty { grid-column: 1 / -1; }

    .vnr-bt__it { display: flex; align-items: flex-start; gap: var(--space-2, 8px); min-inline-size: 0;
      padding: 8px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); cursor: pointer; }
    .vnr-bt__it:hover { border-color: var(--primary-base); }
    .vnr-bt__it.is-sel { border-color: var(--primary-base); background: var(--primary-bg-subtle); }
    /* Không đủ điều kiện: nền mờ + viền đứt + con trỏ chặn — kèm chữ lý do ở .rs */
    .vnr-bt__it.is-off { background: var(--faded-bg); border-style: dashed;
      border-color: var(--border-soft); cursor: not-allowed; }
    .vnr-bt__it.is-off:hover { border-color: var(--border-soft); }
    .vnr-bt__it > input { flex: none; margin: 2px 0 0; accent-color: var(--primary-base); }
    .vnr-bt__it .tx { display: flex; flex-direction: column; gap: 2px; min-inline-size: 0; }
    .vnr-bt__it .nm { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); word-break: break-word; }
    .vnr-bt__it.is-off .nm { color: var(--text-sub); }
    .vnr-bt__it .sb { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-bt__it .rs { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--warning-base); }

    .vnr-bt__ft { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2, 8px); }
    .vnr-bt__ft .sp { margin-inline-start: auto; }
    .vnr-bt__b { border: 1px solid var(--border-strong); background: var(--bg-surface);
      color: var(--text-body); border-radius: var(--radius-sm, 6px); padding: 6px 12px; font: inherit;
      font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); cursor: pointer; }
    .vnr-bt__b:hover:not(:disabled) { border-color: var(--primary-base); color: var(--primary-base); }
    .vnr-bt__b:disabled { opacity: .5; cursor: not-allowed; }
    .vnr-bt__b.is-primary { background: var(--primary-base); border-color: var(--primary-base);
      color: var(--text-on-primary); font-weight: var(--font-semibold, 600); }
    .vnr-bt__b.is-primary:hover:not(:disabled) { color: var(--text-on-primary); opacity: .92; }

    .vnr-bt__pv { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); overflow: hidden; }
    .vnr-bt__pvhd { display: flex; align-items: baseline; gap: var(--space-2, 8px); padding: 8px 12px;
      background: var(--bg-surface-subtle); border-block-end: 1px solid var(--border-soft); }
    .vnr-bt__pvhd .t { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-bt__pvhd .m { margin-inline-start: auto; font-size: var(--fs-11, 11px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }

    .vnr-bt__tb { inline-size: 100%; border-collapse: collapse; }
    .vnr-bt__tb th { background: var(--bg-surface); font-size: var(--fs-11, 11px); text-transform: uppercase;
      letter-spacing: .3px; color: var(--text-soft); font-weight: var(--font-semibold, 600); text-align: start; padding: 7px 10px;
      border-block-end: 1px solid var(--border-soft); }
    .vnr-bt__tb td { padding: 7px 10px; font-size: var(--fs-12, 12px);
      border-block-end: 1px solid var(--border-soft); }
    .vnr-bt__tb tbody tr:last-child td { border-block-end: none; }
    .vnr-bt__tb .lb { color: var(--text-sub); }
    .vnr-bt__tb .vl { color: var(--text-body); font-variant-numeric: tabular-nums; word-break: break-word; }
    .vnr-bt__tb .vl.new { font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-bt__tb .ar { inline-size: 26px; text-align: center; color: var(--text-soft); }
    /* Không đổi ⇒ mờ để mắt tập trung vào phần THỰC SỰ thay đổi */
    .vnr-bt__tb tr.is-same { opacity: .55; }

    .vnr-bt__cards { display: none; flex-direction: column; gap: 6px; padding: 8px; }
    .vnr-bt__card { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); background: var(--bg-surface); }
    .vnr-bt__card.is-same { opacity: .55; }
    .vnr-bt__card .lb { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-bt__card .pair { display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px; }
    .vnr-bt__card .vl { font-size: var(--fs-13, 13px); color: var(--text-body); font-variant-numeric: tabular-nums; }
    .vnr-bt__card .vl.new { font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-bt__card .ar { color: var(--text-soft); }
    .vnr-bt__card .sm { font-size: var(--fs-11, 11px); color: var(--text-soft); }

    .vnr-bt__empty { text-align: center; color: var(--text-soft); font-size: var(--fs-12, 12px); padding: 14px; }

    .vnr-bt__rs { border: 1px solid transparent; border-radius: var(--radius-sm, 6px); padding: 9px 12px;
      font-size: var(--fs-12, 12px); }
    /* Thành công MỘT PHẦN là trạng thái bình thường của thao tác hàng loạt ⇒ tô cảnh báo, không phải lỗi */
    .vnr-bt__rs[data-tone='ok'] { background: var(--success-bg); border-color: var(--success-base); }
    .vnr-bt__rs[data-tone='partial'] { background: var(--warning-bg); border-color: var(--warning-border); }
    .vnr-bt__rs .line { display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px; }
    .vnr-bt__rs .k { color: var(--text-sub); }
    .vnr-bt__rs .dot { color: var(--text-soft); }
    .vnr-bt__rs .v { font-weight: var(--font-bold, 700); font-variant-numeric: tabular-nums; }
    .vnr-bt__rs .v.ok { color: var(--success-base); }
    .vnr-bt__rs .v.fa { color: var(--error-base); }
    .vnr-bt__rs .nt { margin-block-start: 4px; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--text-body); }

    /* Đổi vai theo BỀ RỘNG CONTAINER (không phải viewport) */
    @container vnrform (max-width: 559px) {
      .vnr-bt__tb { display: none; }
      .vnr-bt__cards { display: flex; }
      .vnr-bt__ft .vnr-bt__b { flex: 1 1 100%; }
      .vnr-bt__ft .sp { display: none; }
    }
  `],
})
export class VnrBulkTargetPanel {
  /** Danh sách đối tượng; `eligible` do domain service quyết, UI không tự chấm. */
  readonly targets = input.required<readonly VnrBulkTarget[]>();
  readonly selectedIds = model<readonly string[]>([]);
  /** Dòng "trước → sau" ĐÃ TÍNH sẵn bên ngoài. */
  readonly previewRows = input<readonly VnrBulkPreviewRow[]>([]);
  readonly result = input<VnrBulkResult | null>(null);
  readonly applyLabel = input('Áp dụng');

  readonly selectionChange = output<readonly string[]>();
  readonly preview = output<void>();
  readonly apply = output<readonly string[]>();

  /** Trạng thái hiển thị THUẦN UI — không phải dữ liệu nghiệp vụ. */
  protected readonly showPreview = signal(false);

  protected readonly total = computed(() => this.targets().length);
  protected readonly selectedCount = computed(() => this.selectedIds().length);
  protected readonly ineligibleCount = computed(() => this.targets().filter((t) => !t.eligible).length);
  protected readonly eligibleIds = computed(() => this.targets().filter((t) => t.eligible).map((t) => t.id));
  protected readonly changedCount = computed(() => this.previewRows().filter((r) => r.changed).length);
  protected readonly allSelected = computed(() => {
    const e = this.eligibleIds();
    const s = this.selectedIds();
    return e.length > 0 && e.every((id) => s.includes(id));
  });

  protected isSel(id: string): boolean { return this.selectedIds().includes(id); }

  protected toggle(t: VnrBulkTarget): void {
    if (!t.eligible) return;
    const cur = this.selectedIds();
    const next = cur.includes(t.id) ? cur.filter((x) => x !== t.id) : [...cur, t.id];
    this.selectedIds.set(next);
    this.selectionChange.emit(next);
  }

  protected toggleAll(): void {
    const next = this.allSelected() ? [] : this.eligibleIds();
    this.selectedIds.set(next);
    this.selectionChange.emit(next);
  }

  /** Mở/đóng khối xem trước; lần MỞ mới bắn `preview` để caller tính lại before/after. */
  protected togglePreview(): void {
    const next = !this.showPreview();
    this.showPreview.set(next);
    if (next) this.preview.emit();
  }

  /** Chỉ ĐỊNH DẠNG hiển thị — không phải tính toán nghiệp vụ. */
  protected fmt(v: number): string { return new Intl.NumberFormat('vi-VN').format(v); }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · import-map — nhập dữ liệu hàng loạt từ tệp
// ══════════════════════════════════════════════════════════════════════════════

/** 4 bước cố định của mọi luồng nhập tệp: chọn tệp → ghép cột → kiểm tra → kết quả. */
export type VnrImportStep = 'upload' | 'mapping' | 'preview' | 'result';

/** Một trường của HỆ THỐNG cần được ghép với một cột trong tệp. */
export interface VnrImportTargetField {
  readonly key: string;
  readonly label: string;
  readonly required?: boolean;
}

/** targetKey → tên cột trong tệp (null = chưa ghép). */
export type VnrImportMapping = Record<string, string | null>;

/** Sự kiện đổi ghép cột của MỘT trường. */
export interface VnrImportMappingChange {
  readonly targetKey: string;
  readonly sourceColumn: string | null;
}

/** Một dòng dữ liệu xem trước; `error` do tầng validate BÊN NGOÀI sinh. */
export interface VnrImportPreviewRow {
  readonly rowNo: number;
  /** targetKey → giá trị hiển thị. */
  readonly cells: Record<string, string | null>;
  readonly error?: string | null;
}

/** Kết quả nhập — cho phép thành công một phần. */
export interface VnrImportResult {
  readonly total: number;
  readonly ok: number;
  readonly failed: number;
}

/**
 * Trình nhập dữ liệu hàng loạt từ tệp: stepper 4 bước (hrm-stepper của design system),
 * ghép cột tệp ↔ trường hệ thống, xem trước có đánh dấu dòng lỗi, và trang kết quả.
 *
 * RANH GIỚI: component KHÔNG đọc tệp, KHÔNG phân tích CSV/Excel, KHÔNG validate dữ liệu,
 * KHÔNG tự chạy tiến trình nhập. Nó bắn `fileSelect` / `mappingChange` / `runImport` /
 * `downloadErrors` / `back` rồi hiển thị đúng những gì caller truyền xuống
 * (`sourceColumns`, `previewRows`, `progress`, `result`).
 * ⇒ Dùng lại được cho: import nhân viên · bảng công · lương · số dư phép · danh mục.
 */
@Component({
  selector: 'vnr-import-mapper',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmStepper, HrmProgress, HrmAlert, HrmEmpty],
  template: `
    <div class="vnr-im">
      <!-- Stepper của design system: chỉ phản ánh bước hiện tại, không tự điều hướng tiến.
           activeIndex bind MỘT CHIỀU vì nguồn sự thật là model step(); clickableBack (mặc định true)
           đúng ngữ nghĩa "chỉ cho lùi về bước đã xong". -->
      <hrm-stepper [steps]="stepperSteps()" [activeIndex]="stepIndex()"
        (stepClick)="goTo($any($event).key)" />

      @if (progress() !== null) {
        <hrm-progress [percent]="progress()!" [status]="progress() === 100 ? 'success' : 'active'" size="small" />
      }

      @switch (step()) {

        @case ('upload') {
          <label class="vnr-im__up">
            <input type="file" (change)="onFile($event)" />
            <span class="t">Chọn tệp dữ liệu để nhập</span>
            <span class="h">Hỗ trợ tệp theo mẫu của hệ thống. Tệp sẽ được đọc và kiểm tra ở bước tiếp theo.</span>
            @if (fileName()) { <span class="fn">{{ fileName() }}</span> }
          </label>
        }

        @case ('mapping') {
          <div class="vnr-im__hd">
            <span class="t">Ghép cột trong tệp với trường hệ thống</span>
            <span class="m">Đã ghép {{ mappedCount() }}/{{ targetFields().length }} trường</span>
          </div>
          @if (missingRequired().length) {
            <!-- Cảnh báo bằng CHỮ, không chỉ dựa vào màu -->
            <hrm-alert type="warning"
              [message]="'Còn ' + missingRequired().length + ' trường bắt buộc chưa được ghép cột'"
              [description]="missingRequiredLabels()" />
          }
          <div class="vnr-im__mp">
            @for (f of targetFields(); track f.key) {
              <div class="vnr-im__row" [class.is-miss]="isMissing(f)">
                <span class="fl">
                  <span class="nm">{{ f.label }}@if (f.required) {<span class="rq">*</span>}</span>
                  @if (isMissing(f)) { <span class="ms">Bắt buộc — chưa ghép cột</span> }
                </span>
                <select class="vnr-im__sel" (change)="pick(f.key, $event)"
                  [attr.aria-label]="'Cột nguồn cho trường ' + f.label">
                  <option value="" [selected]="!mapping()[f.key]">— Chưa ghép —</option>
                  @for (c of sourceColumns(); track c) {
                    <option [value]="c" [selected]="mapping()[f.key] === c">{{ c }}</option>
                  }
                </select>
              </div>
            } @empty {
              <hrm-empty preset="no-data" description="Chưa khai báo trường hệ thống nào." />
            }
          </div>
          <div class="vnr-im__ft">
            <button type="button" class="vnr-im__b" (click)="goBack()">Quay lại</button>
            <span class="sp"></span>
            <button type="button" class="vnr-im__b is-primary" (click)="step.set('preview')">Xem trước dữ liệu</button>
          </div>
        }

        @case ('preview') {
          <div class="vnr-im__hd">
            <span class="t">Kiểm tra dữ liệu trước khi nhập</span>
            <span class="m">{{ previewRows().length }} dòng · {{ errorCount() }} dòng lỗi</span>
          </div>

          <div class="vnr-im__tbw">
            <table class="vnr-im__tb">
              <thead><tr>
                <th class="no">Dòng</th>
                @for (f of targetFields(); track f.key) { <th>{{ f.label }}</th> }
              </tr></thead>
              <tbody>
                @for (r of previewRows(); track r.rowNo) {
                  <tr [attr.data-err]="r.error ? 'yes' : null">
                    <td class="no">{{ r.rowNo }}</td>
                    @for (f of targetFields(); track f.key) { <td>{{ r.cells[f.key] || '—' }}</td> }
                  </tr>
                  @if (r.error) {
                    <tr class="er"><td [attr.colspan]="colCount()">{{ r.error }}</td></tr>
                  }
                } @empty {
                  <tr><td class="vnr-im__empty" [attr.colspan]="colCount()">Chưa có dòng dữ liệu nào.</td></tr>
                }
              </tbody>
            </table>
          </div>

          <!-- Card fallback (container hẹp) — cùng dữ liệu, không cuộn ngang -->
          <div class="vnr-im__cards">
            @for (r of previewRows(); track r.rowNo) {
              <div class="vnr-im__card" [attr.data-err]="r.error ? 'yes' : null">
                <div class="hd"><span class="no">Dòng {{ r.rowNo }}</span></div>
                <div class="bd">
                  @for (f of targetFields(); track f.key) {
                    <span><span class="k">{{ f.label }}:</span> <b>{{ r.cells[f.key] || '—' }}</b></span>
                  }
                </div>
                @if (r.error) { <div class="er">{{ r.error }}</div> }
              </div>
            } @empty {
              <div class="vnr-im__empty">Chưa có dòng dữ liệu nào.</div>
            }
          </div>

          <div class="vnr-im__ft">
            <button type="button" class="vnr-im__b" (click)="goBack()">Quay lại</button>
            @if (errorCount()) {
              <button type="button" class="vnr-im__b" (click)="downloadErrors.emit()">Tải file lỗi</button>
            }
            <span class="sp"></span>
            <button type="button" class="vnr-im__b is-primary" (click)="runImport.emit()">Bắt đầu nhập</button>
          </div>
        }

        @case ('result') {
          @if (result(); as r) {
            <div class="vnr-im__rs">
              <div data-t="total"><span class="k">Tổng số dòng</span><span class="v">{{ fmt(r.total) }}</span></div>
              <div data-t="ok"><span class="k">Nhập thành công</span><span class="v">{{ fmt(r.ok) }}</span></div>
              <div data-t="failed"><span class="k">Thất bại</span><span class="v">{{ fmt(r.failed) }}</span></div>
            </div>
            @if (r.failed > 0) {
              <hrm-alert type="warning"
                [message]="fmt(r.failed) + ' dòng chưa được nhập'"
                description="Tải tệp lỗi để sửa rồi nhập lại phần còn thiếu." />
            }
            <div class="vnr-im__ft">
              <button type="button" class="vnr-im__b" (click)="goBack()">Quay lại</button>
              @if (r.failed > 0) {
                <span class="sp"></span>
                <button type="button" class="vnr-im__b is-primary" (click)="downloadErrors.emit()">Tải file lỗi</button>
              }
            </div>
          } @else {
            <div class="vnr-im__empty">Đang chờ kết quả nhập dữ liệu.</div>
          }
        }
      }
    </div>
  `,
  styles: [`
    .vnr-im { display: flex; flex-direction: column; gap: var(--space-3, 12px); }

    .vnr-im__up:focus-within { outline: 2px solid var(--primary-base); outline-offset: 2px; }
    .vnr-im__up { position: relative; display: flex; flex-direction: column; align-items: center; gap: 5px;
      padding: 22px 16px; text-align: center; cursor: pointer; background: var(--bg-surface-subtle);
      border: 1px dashed var(--border-strong); border-radius: var(--radius-sm, 6px); }
    .vnr-im__up:hover { border-color: var(--primary-base); }
    .vnr-im__up input { position: absolute; inline-size: 1px; block-size: 1px; opacity: 0; }
    .vnr-im__up .t { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-im__up .h { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-im__up .fn { margin-block-start: 4px; font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600);
      color: var(--primary-base); background: var(--primary-bg-subtle); border-radius: var(--radius-xs, 4px); padding: 3px 10px; }

    .vnr-im__hd { display: flex; align-items: baseline; gap: var(--space-2, 8px); }
    .vnr-im__hd .t { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-im__hd .m { margin-inline-start: auto; font-size: var(--fs-11, 11px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }
    .vnr-im__mp { display: flex; flex-direction: column; gap: 6px; }
    .vnr-im__row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-2-5, 10px);
      align-items: center; padding: 7px 10px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm, 6px); background: var(--bg-surface); }
    .vnr-im__row.is-miss { border-color: var(--warning-border); background: var(--warning-bg); }
    .vnr-im__row .fl { display: flex; flex-direction: column; gap: 2px; min-inline-size: 0; }
    .vnr-im__row .nm { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-im__row .rq { color: var(--error-base); margin-inline-start: 2px; }
    .vnr-im__row .ms { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--warning-base); }
    .vnr-im__sel { inline-size: 100%; block-size: 30px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-xs, 4px); background: var(--bg-surface); color: var(--text-strong);
      font: inherit; font-size: var(--fs-12, 12px); padding: 0 6px; }
    .vnr-im__sel:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-im__sel:focus { outline: none; border-color: var(--primary-base); }

    .vnr-im__tbw { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); overflow: hidden; }
    .vnr-im__tb { inline-size: 100%; border-collapse: collapse; }
    .vnr-im__tb th { background: var(--bg-surface-subtle); font-size: var(--fs-11, 11px); text-transform: uppercase;
      letter-spacing: .3px; color: var(--text-soft); font-weight: var(--font-semibold, 600); text-align: start; padding: 7px 10px;
      border-block-end: 1px solid var(--border-soft); }
    .vnr-im__tb td { padding: 6px 10px; font-size: var(--fs-12, 12px); color: var(--text-body);
      border-block-end: 1px solid var(--border-soft); }
    .vnr-im__tb .no { inline-size: 56px; color: var(--text-soft); font-variant-numeric: tabular-nums; }
    /* Dòng lỗi: tô nền KÈM dòng chữ mô tả lỗi ngay bên dưới */
    .vnr-im__tb tr[data-err='yes'] td { background: var(--error-bg); border-block-end-color: var(--error-bg); }
    .vnr-im__tb tr.er td { background: var(--error-bg); color: var(--error-base); font-size: var(--fs-11, 11px);
      font-weight: var(--font-semibold, 600); padding-block-start: 0; }

    .vnr-im__cards { display: none; flex-direction: column; gap: 6px; }
    .vnr-im__card { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); padding: 8px 10px; }
    .vnr-im__card[data-err='yes'] { background: var(--error-bg); border-color: var(--error-base); }
    .vnr-im__card .no { font-size: var(--fs-12, 12px); font-weight: var(--font-bold, 700); color: var(--text-strong);
      font-variant-numeric: tabular-nums; }
    .vnr-im__card .bd { display: flex; flex-wrap: wrap; gap: 4px 12px; margin-block-start: 4px;
      font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-im__card .bd b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .vnr-im__card .er { margin-block-start: 5px; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--error-base); }

    .vnr-im__rs { display: flex; flex-wrap: wrap; gap: var(--space-2-5, 10px); }
    .vnr-im__rs > div { flex: 1 1 140px; display: flex; flex-direction: column; gap: 3px; padding: 10px 12px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); background: var(--bg-surface); }
    .vnr-im__rs .k { font-size: var(--fs-11, 11px); color: var(--text-sub); }
    .vnr-im__rs .v { font-size: var(--fs-14, 14px); font-weight: var(--font-bold, 700); color: var(--text-strong);
      font-variant-numeric: tabular-nums; }
    .vnr-im__rs > div[data-t='ok'] { background: var(--success-bg); border-color: var(--success-base); }
    .vnr-im__rs > div[data-t='ok'] .v { color: var(--success-base); }
    .vnr-im__rs > div[data-t='failed'] { background: var(--error-bg); border-color: var(--error-base); }
    .vnr-im__rs > div[data-t='failed'] .v { color: var(--error-base); }

    .vnr-im__ft { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2, 8px); }
    .vnr-im__ft .sp { margin-inline-start: auto; }
    .vnr-im__b { border: 1px solid var(--border-strong); background: var(--bg-surface);
      color: var(--text-body); border-radius: var(--radius-sm, 6px); padding: 6px 12px; font: inherit;
      font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); cursor: pointer; }
    .vnr-im__b:hover:not(:disabled) { border-color: var(--primary-base); color: var(--primary-base); }
    .vnr-im__b:disabled { opacity: .5; cursor: not-allowed; }
    .vnr-im__b.is-primary { background: var(--primary-base); border-color: var(--primary-base);
      color: var(--text-on-primary); font-weight: var(--font-semibold, 600); }
    .vnr-im__b.is-primary:hover:not(:disabled) { color: var(--text-on-primary); opacity: .92; }

    .vnr-im__empty { text-align: center; color: var(--text-soft); font-size: var(--fs-12, 12px); padding: 14px; }

    /* Đổi vai theo BỀ RỘNG CONTAINER (không phải viewport) */
    @container vnrform (max-width: 559px) {
      .vnr-im__tbw { display: none; }
      .vnr-im__cards { display: flex; }
      .vnr-im__row { grid-template-columns: minmax(0, 1fr); gap: 4px; }
      .vnr-im__ft .vnr-im__b { flex: 1 1 100%; }
      .vnr-im__ft .sp { display: none; }
    }
  `],
})
export class VnrImportMapper {
  readonly step = model<VnrImportStep>('upload');
  readonly fileName = input<string | null>(null);
  /** Tên cột ĐỌC ĐƯỢC từ tệp — do caller phân tích tệp rồi truyền vào. */
  readonly sourceColumns = input<readonly string[]>([]);
  readonly targetFields = input.required<readonly VnrImportTargetField[]>();
  readonly mapping = model<VnrImportMapping>({});
  /** Dòng xem trước; `error` do tầng validate bên ngoài sinh. */
  readonly previewRows = input<readonly VnrImportPreviewRow[]>([]);
  /** 0–100, chỉ HIỂN THỊ; component không tự chạy tiến trình. */
  readonly progress = input<number | null>(null);
  readonly result = input<VnrImportResult | null>(null);

  readonly fileSelect = output<File | null>();
  readonly mappingChange = output<VnrImportMappingChange>();
  readonly runImport = output<void>();
  readonly downloadErrors = output<void>();
  readonly back = output<void>();

  protected readonly steps: readonly { key: VnrImportStep; label: string }[] = [
    { key: 'upload', label: 'Chọn tệp' },
    { key: 'mapping', label: 'Ghép cột' },
    { key: 'preview', label: 'Kiểm tra' },
    { key: 'result', label: 'Kết quả' },
  ];

  protected readonly stepIndex = computed(() => {
    const i = this.steps.findIndex((s) => s.key === this.step());
    return i < 0 ? 0 : i;
  });

  /** Chuyển 4 bước nội bộ sang dạng hrm-stepper hiểu được (key giữ nguyên để map ngược khi bấm). */
  protected readonly stepperSteps = computed<HrmStepperStep[]>(
    () => this.steps.map((s) => ({ key: s.key, label: s.label })),
  );

  protected readonly mappedCount = computed(() => this.targetFields().filter((f) => !!this.mapping()[f.key]).length);
  protected readonly missingRequired = computed(() => this.targetFields().filter((f) => !!f.required && !this.mapping()[f.key]));
  protected readonly missingRequiredLabels = computed(() => this.missingRequired().map((f) => f.label).join(', '));
  protected readonly errorCount = computed(() => this.previewRows().filter((r) => !!r.error).length);
  /** Số cột của bảng xem trước = cột "Dòng" + mỗi trường hệ thống một cột. */
  protected readonly colCount = computed(() => this.targetFields().length + 1);

  protected isMissing(f: VnrImportTargetField): boolean {
    return !!f.required && !this.mapping()[f.key];
  }

  /** Chỉ CHUYỂN TIẾP tệp cho caller — component không đọc, không phân tích nội dung. */
  protected onFile(e: Event): void {
    const el = e.target as HTMLInputElement;
    const f = el.files && el.files.length ? el.files[0] : null;
    this.fileSelect.emit(f);
    // Cho phép chọn lại đúng tệp vừa chọn (input file không bắn change nếu giá trị không đổi)
    el.value = '';
  }

  protected pick(targetKey: string, e: Event): void {
    const raw = (e.target as HTMLSelectElement).value;
    const sourceColumn = raw === '' ? null : raw;
    this.mapping.set({ ...this.mapping(), [targetKey]: sourceColumn });
    this.mappingChange.emit({ targetKey, sourceColumn });
  }

  /** Lùi về bước liền trước. Mọi điều hướng LÙI đều bắn `back` để caller đồng bộ trạng thái. */
  protected goBack(): void {
    const i = this.stepIndex();
    if (i <= 0) return;
    this.step.set(this.steps[i - 1].key);
    this.back.emit();
  }

  /** Nhảy về một bước ĐÃ HOÀN THÀNH từ stepper; không cho nhảy tiến. */
  protected goTo(key: VnrImportStep): void {
    const i = this.steps.findIndex((s) => s.key === key);
    if (i < 0 || i >= this.stepIndex()) return;
    this.step.set(key);
    this.back.emit();
  }

  /** Chỉ ĐỊNH DẠNG hiển thị — không phải tính toán nghiệp vụ. */
  protected fmt(v: number): string { return new Intl.NumberFormat('vi-VN').format(v); }
}
