/** ══ "DOMAIN SERVICE" giả lập — TOÀN BỘ công thức nghiệp vụ nằm NGOÀI component ══════
 *
 *  Ba shell dùng trong trang này (`vnr-bulk-target-panel`, `vnr-editable-form-table`,
 *  `vnr-import-mapper`) đều KHÔNG tự chấm điều kiện, KHÔNG cộng tổng, KHÔNG đọc tệp và
 *  KHÔNG validate dữ liệu. Chúng nhận số liệu ĐÃ TÍNH rồi bắn sự kiện ra ngoài.
 *  Các hàm dưới đây chính là "bên ngoài" đó — đặt ở cấp module để ràng buộc kiến trúc
 *  được thực thi bằng THIẾT KẾ, không bằng lời nhắc. */

/** Nhân viên trong phạm vi đợt điều chỉnh. `eligible` do tầng nghiệp vụ chấm sẵn. */
interface Employee {
  readonly id: string;
  readonly code: string;
  readonly name: string;
  readonly dept: string;
  readonly salary: number;
  readonly eligible: boolean;
  readonly reason?: string | null;
}

/** Mức tăng người dùng gõ vào bảng, khoá theo id nhân viên. */
type RaiseMap = Record<string, number | null>;

const EMPLOYEES: readonly Employee[] = [
  { id: 'e1', code: 'NV-0107', name: 'Nguyễn Thu Hà', dept: 'Kỹ thuật · Kỹ sư trưởng', salary: 24500000, eligible: true },
  { id: 'e2', code: 'NV-0112', name: 'Trần Minh Khoa', dept: 'Kỹ thuật · Chuyên viên', salary: 18200000, eligible: true },
  { id: 'e3', code: 'NV-0134', name: 'Vũ Hải Yến', dept: 'Dự án · Trợ lý dự án', salary: 14800000, eligible: true },
  { id: 'e4', code: 'NV-0141', name: 'Lê Thu Hương', dept: 'Kinh doanh · Chuyên viên', salary: 16400000, eligible: false, reason: 'Đang thử việc — chưa đủ 2 tháng chính thức' },
  { id: 'e5', code: 'NV-0150', name: 'Phạm Quốc Duy', dept: 'Vận hành · Tổ trưởng', salary: 19700000, eligible: true },
  { id: 'e6', code: 'NV-0158', name: 'Đỗ Kim Ngân', dept: 'Nhân sự · Chuyên viên', salary: 15300000, eligible: false, reason: 'Đã nghỉ việc từ 30/06/2026' },
];

const EMP_BY_ID = new Map<string, Employee>(EMPLOYEES.map((e) => [e.id, e]));

/** Mức tăng vượt tỉ lệ này so với lương hiện tại phải trình thêm một cấp duyệt. */
const RAISE_WARN_RATIO = 0.3;

const NUMBER_FORMAT = new Intl.NumberFormat('vi-VN');

/** Chỉ ĐỊNH DẠNG hiển thị — không phải tính toán nghiệp vụ. */
function money(v: number): string {
  return NUMBER_FORMAT.format(v);
}

/** Lấy mức tăng đã nhập của một nhân viên; chưa nhập hoặc không hợp lệ ⇒ 0. */
function raiseOf(raises: RaiseMap, id: string): number {
  const v = raises[id];
  return typeof v === 'number' && Number.isFinite(v) ? v : 0;
}

/** Dựng danh sách đối tượng cho panel chọn. Điều kiện áp dụng do NGHIỆP VỤ quyết,
 *  panel chỉ hiển thị và đếm. */
function buildTargets(emps: readonly Employee[]): VnrBulkTarget[] {
  return emps.map((e) => ({
    id: e.id,
    name: e.name,
    sub: `${e.code} · ${e.dept} · ${money(e.salary)} ₫`,
    eligible: e.eligible,
    reason: e.reason ?? null,
  }));
}

/** Lỗi của một dòng bảng — kiểm tra ở đây, `vnr-editable-form-table` chỉ tô và in chữ. */
function rowError(e: Employee, raise: number): string | null {
  if (raise < 0) return 'Mức tăng phải là số dương — để trống nếu chưa điều chỉnh.';
  if (raise > e.salary * RAISE_WARN_RATIO) {
    return `Mức tăng vượt ${RAISE_WARN_RATIO * 100}% lương hiện tại (${money(Math.round(e.salary * RAISE_WARN_RATIO))} ₫) — cần Tổng giám đốc phê duyệt.`;
  }
  return null;
}

/** Dựng dòng bảng nhập từ danh sách đã chọn.
 *  Ba cột "Nhân viên · Lương hiện tại · Lương mới" là readonly vì đều do NGHIỆP VỤ tính;
 *  chỉ cột "Mức tăng" người dùng gõ. Cột "Lương mới" = lương hiện tại + mức tăng,
 *  phép cộng nằm TẠI ĐÂY chứ không nằm trong component bảng. */
function buildTableRows(ids: readonly string[], raises: RaiseMap): VnrFormTableRow[] {
  const out: VnrFormTableRow[] = [];
  for (const id of ids) {
    const e = EMP_BY_ID.get(id);
    if (!e) continue;
    const raise = raiseOf(raises, id);
    out.push({
      id: e.id,
      cells: {
        emp: `${e.name} (${e.code})`,
        current: e.salary,
        raise: raises[id] ?? null,
        next: e.salary + raise,
      },
      error: rowError(e, raise),
    });
  }
  return out;
}

/** Tổng cột "Mức tăng" — CỘNG Ở ĐÂY. `vnr-editable-form-table` tuyệt đối không cộng tổng,
 *  nó chỉ đặt giá trị nhận được vào đúng cột theo `key`. */
function sumRaise(rows: readonly VnrFormTableRow[]): VnrFormTableTotal[] {
  const total = rows.reduce((s, r) => {
    const v = r.cells['raise'];
    return s + (typeof v === 'number' && Number.isFinite(v) ? v : 0);
  }, 0);
  return [{ key: 'raise', value: total }];
}

/** Dòng "trước → sau" cho panel xem trước — panel không tự tính before/after. */
function buildPreviewRows(ids: readonly string[], raises: RaiseMap): VnrBulkPreviewRow[] {
  const out: VnrBulkPreviewRow[] = [];
  for (const id of ids) {
    const e = EMP_BY_ID.get(id);
    if (!e) continue;
    const raise = raiseOf(raises, id);
    out.push({
      id: e.id,
      label: `${e.name} · ${e.code}`,
      before: `${money(e.salary)} ₫`,
      after: `${money(e.salary + raise)} ₫`,
      changed: raise > 0,
    });
  }
  return out;
}

/** Giả lập kết quả áp dụng — cho phép THÀNH CÔNG MỘT PHẦN.
 *  Quy ước nghiệp vụ của bản mẫu này: nhân viên không đủ điều kiện trong đợt tính là
 *  THẤT BẠI (bị hệ thống bỏ qua), dòng đã chọn nhưng chưa nhập mức tăng cũng bỏ qua. */
function applyAdjustment(ids: readonly string[], raises: RaiseMap): VnrBulkResult {
  const picked = ids.map((id) => EMP_BY_ID.get(id)).filter((e): e is Employee => !!e);
  const ok = picked.filter((e) => e.eligible && raiseOf(raises, e.id) > 0).length;
  const noRaise = picked.filter((e) => e.eligible && raiseOf(raises, e.id) <= 0).length;
  const blocked = EMPLOYEES.filter((e) => !e.eligible);

  const notes: string[] = [];
  if (blocked.length) {
    notes.push(`${blocked.length} nhân viên không đủ điều kiện: ` +
      blocked.map((e) => `${e.name} (${e.reason})`).join('; '));
  }
  if (noRaise) notes.push(`${noRaise} dòng chưa nhập mức tăng nên bị bỏ qua.`);

  return {
    ok,
    failed: noRaise + blocked.length,
    failedNote: notes.length ? notes.join(' · ') : null,
  };
}

/** ══ Nhánh IMPORT — tệp, cột nguồn, ghép cột và validate đều là việc của NGHIỆP VỤ ══ */

/** Cột đọc được từ tệp Excel mẫu (bình thường do tầng phân tích tệp trả về). */
const IMPORT_SOURCE_COLUMNS: readonly string[] = ['Mã NV', 'Họ tên', 'Lương mới', 'Ghi chú'];

/** Trường của HỆ THỐNG cần được ghép với một cột trong tệp. */
const IMPORT_TARGET_FIELDS: readonly VnrImportTargetField[] = [
  { key: 'code', label: 'Mã nhân viên', required: true },
  { key: 'name', label: 'Họ tên' },
  { key: 'newSalary', label: 'Lương mới', required: true },
  { key: 'effectiveDate', label: 'Ngày hiệu lực' },
  { key: 'note', label: 'Ghi chú' },
];

/** Nội dung tệp mẫu — cố ý gài 3 loại lỗi thường gặp để thấy bước "Kiểm tra" làm việc. */
const IMPORT_FILE_ROWS: readonly Record<string, string>[] = [
  { 'Mã NV': 'NV-0107', 'Họ tên': 'Nguyễn Thu Hà', 'Lương mới': '26.500.000', 'Ghi chú': 'Đạt KPI quý 2' },
  { 'Mã NV': 'NV-0112', 'Họ tên': 'Trần Minh Khoa', 'Lương mới': '19.400.000', 'Ghi chú': '' },
  { 'Mã NV': 'NV-0134', 'Họ tên': 'Vũ Hải Yến', 'Lương mới': '', 'Ghi chú': 'Chờ xác nhận từ trưởng dự án' },
  { 'Mã NV': 'NV-9999', 'Họ tên': 'Hoàng Anh Tuấn', 'Lương mới': '17.000.000', 'Ghi chú': 'Nhân viên mới' },
  { 'Mã NV': 'NV-0150', 'Họ tên': 'Phạm Quốc Duy', 'Lương mới': '20tr9', 'Ghi chú': 'Tăng theo tay nghề' },
];

/** Gợi ý ghép cột: tên cột trong tệp hiếm khi trùng tên trường hệ thống. */
const COLUMN_HINTS: Record<string, readonly string[]> = {
  code: ['Mã NV', 'Mã nhân viên'],
  name: ['Họ tên', 'Tên nhân viên'],
  newSalary: ['Lương mới', 'Mức lương mới'],
  effectiveDate: ['Ngày hiệu lực', 'Hiệu lực từ'],
  note: ['Ghi chú', 'Diễn giải'],
};

/** Trường TIỀN bắt buộc người dùng tự xác nhận cột nguồn — không tự ghép, tránh ghép nhầm
 *  cột lương cũ thành lương mới. Nhờ vậy màn hình luôn mở ra với đúng một cảnh báo
 *  "còn trường bắt buộc chưa ghép" để người nhập nhìn thấy quy trình. */
const MANUAL_CONFIRM_FIELDS: readonly string[] = ['newSalary'];

/** Ghép cột tự động — thuật toán là việc của nghiệp vụ, `vnr-import-mapper` chỉ hiển thị. */
function autoMap(
  columns: readonly string[],
  fields: readonly VnrImportTargetField[],
): VnrImportMapping {
  const map: VnrImportMapping = {};
  for (const f of fields) {
    if (MANUAL_CONFIRM_FIELDS.includes(f.key)) { map[f.key] = null; continue; }
    const hints = COLUMN_HINTS[f.key] ?? [];
    map[f.key] = columns.find((c) => hints.includes(c)) ?? null;
  }
  return map;
}

/** Đọc số tiền dạng "26.500.000" ⇒ 26500000; không đọc được ⇒ null. */
function parseMoney(text: string): number | null {
  const digits = text.replace(/[.\s]/g, '');
  return /^\d+$/.test(digits) ? Number(digits) : null;
}

/** Validate MỘT dòng import — toàn bộ luật nằm ở đây, component không kiểm tra gì. */
function validateImportRow(cells: Record<string, string | null>): string | null {
  const code = cells['code'];
  if (!code) return 'Thiếu mã nhân viên — chưa ghép cột hoặc ô trống trong tệp.';
  if (!EMPLOYEES.some((e) => e.code === code)) {
    return `Không tìm thấy mã nhân viên ${code} trong hệ thống.`;
  }
  const salary = cells['newSalary'];
  if (!salary) return 'Thiếu lương mới — kiểm tra lại cột đã ghép ở bước trước.';
  if (parseMoney(salary) === null) return `Giá trị lương mới "${salary}" không phải số hợp lệ.`;
  return null;
}

/** Đổ nội dung tệp qua bảng ghép cột để ra dòng xem trước. Đổi ghép cột ⇒ xem trước đổi theo. */
function buildImportPreview(mapping: VnrImportMapping): VnrImportPreviewRow[] {
  return IMPORT_FILE_ROWS.map((raw, i) => {
    const cells: Record<string, string | null> = {};
    for (const f of IMPORT_TARGET_FIELDS) {
      const col = mapping[f.key];
      cells[f.key] = col ? (raw[col] || null) : null;
    }
    return { rowNo: i + 1, cells, error: validateImportRow(cells) };
  });
}

/** Giả lập chạy tiến trình nhập — cũng cho phép thành công một phần. */
function runImportBatch(rows: readonly VnrImportPreviewRow[]): VnrImportResult {
  const total = rows.length;
  const failed = rows.filter((r) => !!r.error).length;
  return { total, ok: total - failed, failed };
}

